import{_ as t,o as a,c as r,ag as d}from"./chunks/framework.IxO3mcwW.js";const i="/getbiji-docs/images/getseed-intro-01.png",o="/getbiji-docs/images/getseed-intro-02.png",l="/getbiji-docs/images/getseed-intro-03.png",m=JSON.parse('{"title":"GetSeed 录音卡","description":"","frontmatter":{},"headers":[],"relativePath":"getseed/index.md","filePath":"getseed/index.md","lastUpdated":1773147350000}'),s={name:"getseed/index.md"};function n(h,e,g,c,p,u){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="getseed-录音卡" tabindex="-1">GetSeed 录音卡 <a class="header-anchor" href="#getseed-录音卡" aria-label="Permalink to &quot;GetSeed 录音卡&quot;">​</a></h1><blockquote><p>于点滴记录里，听见生长</p></blockquote><h2 id="什么是-getseed" tabindex="-1">什么是 GetSeed？ <a class="header-anchor" href="#什么是-getseed" aria-label="Permalink to &quot;什么是 GetSeed？&quot;">​</a></h2><p>GetSeed，Seed 是种子。每一次记录，都是播下一颗知识的种子。你播种，它培育，让知识在你身上生根、发芽、生长。</p><p>大多数录音产品停留在&quot;帮你记住&quot;——录音、转写、存档。笔记越存越多，却变成了信息的坟墓。</p><p>我们相信，记录的真正价值不是&quot;记住&quot;，而是&quot;生长&quot;。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="一键开启录音" tabindex="-1">一键开启录音 <a class="header-anchor" href="#一键开启录音" aria-label="Permalink to &quot;一键开启录音&quot;">​</a></h3><ul><li><strong>打开即录</strong>：拨动开关，1秒开始录音。再拨一下，结束录音。无需解锁、无需找APP</li><li><strong>一键 Mark 重点</strong>：短按 Mark 键，快速标记重点时刻，会后 AI 自动生成重点摘要</li><li><strong>多模态记录</strong>：录音中可拍照、随手记，会后 AI 结合所有内容生成图文并茂的笔记</li></ul><h3 id="通话录音" tabindex="-1">通话录音 <a class="header-anchor" href="#通话录音" aria-label="Permalink to &quot;通话录音&quot;">​</a></h3><p>电话、微信视频、腾讯会议、钉钉、飞书，全都能录。</p><ul><li>普通电话 ✓</li><li>微信语音/视频通话 ✓</li><li>腾讯/钉钉/飞书会议 ✓</li><li>现场录音 ↔ 通话录音，智能识别，自动切换</li></ul><h3 id="闪念随时记" tabindex="-1">闪念随时记 <a class="header-anchor" href="#闪念随时记" aria-label="Permalink to &quot;闪念随时记&quot;">​</a></h3><p>长按 Mark 键，快速记录灵感。AI 自动转写、智能润色、去除口水词、识别方言。</p><p>支持 12 种方言：普通话、英语、粤语、四川话、陕西话、河南话、上海话、湖南话、湖北话、安徽话、闽南话、潮汕话</p><h2 id="为什么需要-getseed" tabindex="-1">为什么需要 GetSeed？ <a class="header-anchor" href="#为什么需要-getseed" aria-label="Permalink to &quot;为什么需要 GetSeed？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>痛点</th><th>GetSeed 解决方案</th></tr></thead><tbody><tr><td>手机录音要解锁、找APP</td><td>盲操一秒开录，物理按键拨动即录</td></tr><tr><td>来电/消息打断录音</td><td>独立运行，手机来电消息都不影响</td></tr><tr><td>手机没电不敢录</td><td>35 小时连续录音，待机 60 天</td></tr><tr><td>通话录不了</td><td>电话、微信、会议软件全都能录</td></tr><tr><td>没网录不了</td><td>64GB 本地存储，录完再同步</td></tr></tbody></table><h2 id="适合谁" tabindex="-1">适合谁？ <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁？&quot;">​</a></h2><ul><li>📋 <strong>会议缠身的职场人</strong>：产品经理、销售、项目经理、管理者</li><li>📚 <strong>终身学习的知识行动派</strong>：考研/考公/考证党、MBA学员、培训常客</li><li>✍️ <strong>深度的内容创作者</strong>：自媒体博主、播客主播、作家/编剧</li><li>💼 <strong>需要留存沟通记录的专业人士</strong>：律师、咨询顾问、记者、创业者</li><li>🏠 <strong>生活场景</strong>：看病记录医嘱、装修沟通、早教课笔记</li></ul><h2 id="产品图片" tabindex="-1">产品图片 <a class="header-anchor" href="#产品图片" aria-label="Permalink to &quot;产品图片&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+i+'" alt="GetSeed外观" style="width:200px;border-radius:8px;"><img src="'+o+'" alt="GetSeed配件" style="width:200px;border-radius:8px;"><img src="'+l+'" alt="使用场景" style="width:200px;border-radius:8px;"></div>',21)])])}const _=t(s,[["render",n]]);export{m as __pageData,_ as default};
